            elif cmd=='NICK':
                n=arg.lstrip(':').strip()
                if n in NICKS and n!=nick:
                    writer.write(f':huddle 433 * {n} :Nickname is already in use\r\n'.encode());await writer.drain();continue
                if nick:NICKS.discard(nick)
                nick=n;NICKS.add(nick)
            elif cmd=='USER':user=arg
