            elif cmd=='PING':
                tok=arg.lstrip(':');writer.write(f':huddle PONG huddle :{tok}\r\n'.encode());await writer.drain()
            elif cmd in ('PONG','NAMES','WHO','LIST','TOPIC','MODE'):continue
            elif cmd=='JOIN' and registered:
                name=arg.split()[0]; ok=False; ch=None
