THOUGHT: The UI still has multiple competing send handlers and initialization layers, making behavior nondeterministic. I will replace the served script with one self-contained implementation that binds on `DOMContentLoaded`, loads the token workspace, posts only nonblank messages, and renders the required message row and three-pane layout.

```mswea_bash_command
cat >/app/static/app.js <<'JS'
document.addEventListener('DOMContentLoaded',()=>{const $=s=>document.querySelector(s),tok=()=>localStorage.getItem('huddle.token');let ws,channel;
async function api(p,o={}){o.headers=Object.assign({'Content-Type':'application/json'},o.headers||{});if(tok())o.headers.Authorization='Bearer '+tok();let r=await fetch('/api'+p,o),d=await r.json();if(!r.ok)throw d;return d}
function auth(v){$('#auth-modal').style.display=v?'block':'none'}
async function open(c){channel=c;$('#channel-title').textContent='#'+c.name;$('#channel-topic').textContent=c.topic||'';let x=await api('/channels/'+c.id+'/messages'),b=$('#message-list');b.innerHTML='';x.messages.forEach(render);$('#channel-empty-state').textContent=x.messages.length?'':'No messages yet'}
function render(m){let r=document.createElement('div');r.dataset.testid='message';r.dataset.messageId=m.id;r.innerHTML='<span class="avatar">'+(m.author.display_name||'U')[0]+'</span><b>'+m.author.display_name+'</b><time>'+new Date(m.created_at).toLocaleString()+'</time><span data-testid="message-body">'+m.body+'</span><button type="button" data-testid="reaction-button">😀</button><button type="button" data-testid="open-thread-btn">Reply</button>';$('#message-list').append(r)}
async function load(){let me=await api('/auth/me');$('#current-user').textContent=me.user.display_name||me.user.username;auth(false);let x=await api('/workspaces');if(x.workspaces[0]){let w=await api('/workspaces/'+x.workspaces[0].slug);$('#workspace-header').textContent=w.workspace.name;let b=$('#channel-list');b.innerHTML='';w.channels.forEach(c=>{let e=document.createElement('button');e.dataset.testid='channel-entry';e.dataset.channelId=c.id;e.dataset.channelName=c.name;e.textContent='#'+c.name;e.onclick=()=>open(c);b.append(e)});if(w.channels[0])open(w.channels[0])}}
$('#send-btn').onclick=async e=>{e.preventDefault();let i=$('#message-input'),v=i.value;if(!v||!v.trim()||!channel)return;let x=await api('/channels/'+channel.id+'/messages',{method:'POST',body:JSON.stringify({body:v.trim()})});i.value='';render(x.message);$('#channel-empty-state').textContent=''}
$('#logout-btn').onclick=()=>{localStorage.removeItem('huddle.token');auth(true)}
$('#auth-form').onsubmit=async e=>{e.preventDefault();let f=e.target,d={username:f.querySelector('[name=username]').value,password:f.querySelector('[name=password]').value};try{let x;try{x=await api('/auth/register',{method:'POST',body:JSON.stringify(d)})}catch(_){x=await api('/auth/login',{method:'POST',body:JSON.stringify(d)})}localStorage.setItem('huddle.token',x.token);await load()}catch(x){let z=$('[data-testid=auth-error]');z.textContent=x.error||'Invalid credentials';z.style.display='block'}}
document.body.style.overflow='hidden';if(tok())load().catch(()=>auth(true));else auth(true)
})
